mapper.select:
select t.*, t1.balance, (select create_time from login_log where user_id = t.id order by create_time desc limit 1) loginTime, (select login_ip from login_log where user_id = t.id order by create_time desc limit 1) loginIp,
p.name platformName from `user` t left join user_wallet t1 on t1.user_id = t.id and t1.deleted = 0 left join platform p on p.id = t.platform_id where t.deleted = 0
and t.id = #{params.id}
and t.platform_id = #{params.platformId}
and t.phone = #{params.phone}
and t.nick_name like CONCAt('%', #{params.nickName,jdbcType=VARCHAR}, '%')
and and t.create_time >= #{params.startTime} and t.create_time <= #{params.endTime}
order by t.online desc

select t.*,
(select create_time from login_log where user_id = t.id order by create_time desc limit 1) loginTime, (select login_ip from login_log where user_id = t.id order by create_time desc limit 1) loginIp, (select login_ip_name from login_log where user_id = t.id order by create_time desc limit 1) loginIpName,
IFNULL(t2.balance, 0) balance from `user` t left join user_wallet t2 on t2.user_id = t.id and t2.deleted = 0 where t.deleted = 0 and t.id = #{userId}
